const data={norte:{name:'Norte Construcción',projects:[['torre','Torre Norte',['Instalaciones eléctricas','Prevención']],['anexo','Anexo Norte',['Logística']]],jobs:[['risk','triangle-alert','Protección colectiva sin confirmar','J. Martín','Hoy · 12:30','2 registros','INC-248','Revisar incidencia'],['amber','package-search','Pedido de cable con recepción incompleta','Oficina técnica','Hoy · 16:00','1 registro','INC-241','Ver entrega'],['info','list-checks','Checklist de seguridad a falta de 2 puntos','Marta Sáez','Hoy · 13:30','4 registros','checklists','Abrir checklist'],['info','map','Plano de Planta 2 con zona pendiente','Marta Sáez','Hoy · 13:30','2 registros','plans','Abrir plano']]},atlas:{name:'Atlas Servicios',projects:[['sur','Centro Logístico Sur',['Logística','Prevención']],['puerto','Terminal Puerto',['Operaciones']]],jobs:[['amber','package-search','Recepción de material por validar','Lucía Campos','Hoy · 15:00','1 registro','INC-241','Ver entrega'],['info','map','Plano de muelle con revisión pendiente','Almacén','Mañana · 09:00','3 registros','plans','Abrir plano'],['info','list-checks','Checklist de recepción pendiente','Lucía Campos','Mañana · 10:00','2 registros','checklists','Abrir checklist']]}};
const incidents=[['INC-248','risk','critical','Crítica','Protección colectiva incompleta','J. Martín','martin','Hoy · 12:30','2','Falta una foto actualizada del perímetro de Planta 2.','Solicitar evidencia y confirmar cierre.'],['INC-241','amber','review','Revisión','Pedido de cable sin albarán','Oficina técnica','office','Hoy · 16:00','1','La recepción parcial necesita el documento de entrega.','Validar albarán con el proveedor.'],['INC-233','info','open','Abierta','Señalización temporal pendiente','J. Martín','martin','Mañana · 09:00','4','El checklist detectó señalización incompleta.','Completar señalización y adjuntar foto.']];let selected=incidents[0],offline=false;
function icons(){window.lucide?.createIcons({'attrs':{'stroke-width':1.8}})}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2500)}function go(v,id){if(id){selected=incidents.find(x=>x[0]===id)||selected;$('#status').value='all';$('#owner').value='all';rows()}$$('.view').forEach(x=>x.classList.toggle('active',x.id===v));$$('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===v));document.body.classList.toggle('chat-open',v==='chat');icons()}function open(t){go(t.startsWith('INC-')?'incidents':t,t.startsWith('INC-')?t:null)}
function context(){let d=data[$('#company').value],p=d.projects.find(x=>x[0]===$('#project').value)||d.projects[0];$('#project').innerHTML=d.projects.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('');$('#project').value=p[0];$('#department').innerHTML=p[2].map(x=>`<option>${x}</option>`).join('');$('#scopeNote').innerHTML=`<i data-lucide="shield-check"></i>Datos simulados: ${d.name} · ${p[1]} · ${$('#department').value}.`;$('#attention').innerHTML=d.jobs.slice(0,3).map(x=>`<article class="attention-item" style="--tone:var(--${x[0]});--toneS:var(--${x[0]}S)"><i data-lucide="${x[1]}"></i><div><h2>${x[2]}</h2><p>Requiere seguimiento dentro del alcance simulado.</p></div><span>Responsable<b>${x[3]}</b></span><span>Vencimiento<b>${x[4]}</b></span><span>Evidencia<b>${x[5]}</b></span><button class="button secondary" data-open="${x[6]}">${x[7]}</button></article>`).join('');$('#workInbox').innerHTML=d.jobs.map(x=>`<article class="panel"><span class="severity ${x[0]}">${x[0]==='risk'?'Incidencia crítica':x[6]==='plans'?'Plano relevante':'Trabajo pendiente'}</span><h2>${x[2]}</h2><p>${x[3]} · ${x[4]} · ${x[5]} de evidencia</p><button class="button secondary" data-open="${x[6]}">Abrir</button></article>`).join('');$$('[data-open]').forEach(x=>x.addEventListener('click',()=>open(x.dataset.open)));icons()}
function detail(x){$('#detail').innerHTML=`<span class="severity ${x[1]}">${x[0]} · ${x[3]}</span><h2>${x[4]}</h2><p>${x[9]}</p><dl><dt>Responsable</dt><dd>${x[5]}</dd><dt>Vence</dt><dd>${x[7]}</dd><dt>Evidencia</dt><dd>${x[8]} registros simulados</dd><dt>Siguiente acción</dt><dd>${x[10]}</dd></dl><button class="button violet">Ver evidencia</button>`}function rows(){let s=$('#status').value,o=$('#owner').value,r=incidents.filter(x=>(s==='all'||x[2]===s)&&(o==='all'||x[6]===o));if(!r.includes(selected))selected=r[0]||incidents[0];$('#rows').innerHTML=r.length?r.map(x=>`<tr data-id="${x[0]}" class="${x===selected?'selected':''}"><td><span class="severity ${x[1]}">${x[3]}</span></td><td><b>${x[4]}</b><br><small>${x[0]}</small></td><td>${x[5]}</td><td>${x[7]}</td><td>${x[8]} registros</td></tr>`).join(''):'<tr><td colspan="5">No hay incidencias para estos filtros simulados.</td></tr>';detail(selected);$$('[data-id]').forEach(x=>x.addEventListener('click',()=>{selected=incidents.find(y=>y[0]===x.dataset.id);rows()}));icons()}
function setup(){let nav=$('aside nav'),work=nav.querySelector('[data-view="incidents"]');work.dataset.view='work';work.lastChild.textContent='Trabajo';let head=document.createElement('em');head.textContent='OPERACIÓN';nav.insertBefore(head,nav.querySelector('[data-view="dashboard"]'));$('.mobile [data-view="incidents"]').dataset.view='work';let section=document.createElement('section');section.className='view';section.id='work';section.innerHTML='<div class="heading"><div><small>TRABAJO · BANDEJA PRIORIZADA</small><h1>Lo siguiente en tu contexto</h1><p>Incidencias, checklists y planos relevantes.</p></div></div><div class="grid two" id="workInbox"></div>';$('main').insertBefore(section,$('#incidents'));let sync=document.createElement('span');sync.id='syncStatus';sync.className='sync';sync.innerHTML='<i data-lucide="cloud-check"></i>Sincronizado';let off=document.createElement('button');off.className='icon';off.innerHTML='<i data-lucide="wifi"></i>';off.setAttribute('aria-label','Alternar modo offline simulado');off.onclick=()=>{offline=!offline;sync.innerHTML=offline?'<i data-lucide="cloud-off"></i>Offline simulado':'<i data-lucide="cloud-check"></i>Sincronizado';toast(offline?'Modo offline simulado: se muestra la última información local.':'Sincronización simulada restablecida.');icons()};$('header>div:last-child').prepend(sync,off);let plan=$('.plan>div'),pd=document.createElement('aside');pd.className='panel';pd.id='planDetail';pd.textContent='Selecciona una marca para ver el trabajo relacionado.';plan.after(pd);$$('.tag').forEach((x,i)=>{let t=['INC-248','INC-241','checklists'][i];x.tabIndex=0;x.setAttribute('role','button');x.onclick=()=>{let z=t==='INC-248'?incidents[0]:t==='INC-241'?incidents[1]:['','info','','','Checklist de seguridad','Marta Sáez','','Hoy · 13:30','4'];pd.innerHTML=`<b>${z[4]}</b><span>Responsable: ${z[5]} · Vence: ${z[7]} · Evidencia: ${z[8]} registros simulados</span><button class="button secondary" data-open="${t}">Abrir trabajo relacionado</button>`;pd.querySelector('button').onclick=()=>open(t)};x.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();x.click()}}});let n=$('#notifications .schedule article'),a=document.createElement('button');a.className='button secondary';a.textContent='Posponer 1 h';a.onclick=()=>{a.textContent='Pospuesto 1 h';a.disabled=true;n.style.opacity='.58';toast('Recordatorio pospuesto 1 h (simulado).')};n.append(a)}
setup();$$('[data-view]').forEach(x=>x.addEventListener('click',()=>go(x.dataset.view)));$('#company').addEventListener('change',context);$('#project').addEventListener('change',context);$('#department').addEventListener('change',context);['status','owner'].forEach(x=>$('#'+x).onchange=rows);$('#clear').onclick=()=>{$('#status').value='all';$('#owner').value='all';rows()};$$('[data-state]').forEach(x=>x.onclick=()=>{$('#state').hidden=false;$('#state').innerHTML=x.dataset.state==='loading'?'<div class="skeleton"><i></i><i></i><i></i></div>':`<article class="demo-state"><h2>${x.dataset.state==='empty'?'No hay informes pendientes':'No se pudo actualizar el panorama'}</h2><p>${x.dataset.state==='empty'?'El alcance simulado no tiene informes.':'La última lectura verificada se conserva; vuelve a intentarlo.'}</p><button class="button secondary">${x.dataset.state==='empty'?'Registrar incidencia':'Reintentar'}</button></article>`});function theme(){document.body.classList.toggle('light');toast(document.body.classList.contains('light')?'Tema claro activado.':'Tema oscuro activado.')}$('#theme').onclick=theme;$('#theme2').onclick=theme;$('#scan').onclick=()=>toast('Escanear es una acción visual simulada; no abre cámara ni procesa datos.');context();rows();icons();
